      <span class="power" aria-hidden="true"></span>
    </div>
  </header>

  <nav id="taskbar" aria-label="Applications">
    <button id="open-files" class="launcher" aria-label="Open Files">
      <span class="folder-icon" aria-hidden="true"></span>
    </button>
    <button id="open-notepad" class="launcher" aria-label="Open Notepad">
      <span class="note-icon" aria-hidden="true"></span>
    </button>
  </nav>

  <section id="files-window" class="window" aria-label="Files window">
    <div class="titlebar">
      <span class="window-title">Files</span>
      <button class="win-close" aria-label="Close Files">×</button>
    </div>
    <div class="files-toolbar">
      <button id="files-up" title="Parent folder" aria-label="Parent folder">↑</button>
      <div id="files-path">/</div>
    </div>
    <div class="files-layout">
      <aside class="sidebar">
        <div class="place active" data-path="/">⌂ &nbsp;Computer</div>
        <div class="place" data-path="/home/user">⌂ &nbsp;Home</div>
        <div class="place" data-path="/home/user/Documents">▤ &nbsp;Documents</div>
        <div class="place" data-path="/home/user/Downloads">↓ &nbsp;Downloads</div>
        <div class="place" data-path="/home/user/Pictures">▧ &nbsp;Pictures</div>
      </aside>
      <main id="files-list" aria-label="Folder contents"></main>
    </div>
  </section>

  <section id="notepad-window" class="window" aria-label="Notepad window">
    <div class="titlebar">
      <span class="window-title">Notepad</span>
      <button class="win-close" aria-label="Close Notepad">×</button>
    </div>
    <div class="notepad-tools">
      <button id="new-tab">＋ New Tab</button>
    </div>
    <div id="tabs" role="tablist"></div>
    <textarea id="editor" spellcheck="true" aria-label="Text editor"></textarea>
  </section>
</div>

<script>
(() => {
  "use strict";

  const fileSystem = {
    "/": [
      ["bin", "folder"], ["etc", "folder"], ["home", "folder"],
      ["usr", "folder"], ["var", "folder"], ["opt", "folder"],
      ["tmp", "folder"], ["README", "file"]
    ],
    "/bin": [
      ["bash", "file"], ["cat", "file"], ["cp", "file"],
      ["ls", "file"], ["mkdir", "file"]
    ],
    "/etc": [
      ["apt", "folder"], ["network", "folder"], ["hosts", "file"],
      ["hostname", "file"], ["os-release", "file"]
    ],
    "/home": [["user", "folder"]],
    "/home/user": [
      ["Documents", "folder"], ["Downloads", "folder"],
      ["Pictures", "folder"], ["Music", "folder"],
      ["Videos", "folder"], ["notes.txt", "file"]
    ],
    "/home/user/Documents": [
      ["Projects", "folder"], ["Ideas.txt", "file"],
      ["Resume.pdf", "file"], ["todo.md", "file"]
    ],
    "/home/user/Documents/Projects": [
      ["desktop-app", "folder"], ["README.md", "file"]
    ],
    "/home/user/Documents/Projects/desktop-app": [
      ["app.html", "file"], ["LICENSE", "file"]
    ],
    "/home/user/Downloads": [
      ["archive.tar.gz", "file"], ["wallpaper.png", "file"]
    ],
    "/home/user/Pictures": [
      ["Wallpapers", "folder"], ["holiday.jpg", "file"],
      ["portrait.png", "file"]
    ],
    "/home/user/Pictures/Wallpapers": [
      ["ubuntu-purple.jpg", "file"], ["mountains.jpg", "file"]
    ],
    "/home/user/Music": [["Playlist.m3u", "file"]],
    "/home/user/Videos": [["welcome.mp4", "file"]],
    "/usr": [
      ["bin", "folder"], ["lib", "folder"], ["local", "folder"],
      ["share", "folder"]
    ],
    "/var": [
      ["cache", "folder"], ["lib", "folder"], ["log", "folder"],
      ["tmp", "folder"]
    ],
    "/opt": [],
    "/tmp": []
  };

  let currentPath = "/";
  let topZ = 20;
  const filesList = document.getElementById("files-list");
  const filesPath = document.getElementById("files-path");
  const upButton = document.getElementById("files-up");

  function joinPath(base, name) {
    return base === "/" ? "/" + name : base + "/" + name;
  }

  function navigate(path) {
    if (!Object.prototype.hasOwnProperty.call(fileSystem, path)) return;
    currentPath = path;
    filesPath.textContent = path;
    upButton.disabled = path === "/";
    filesList.replaceChildren();

    for (const [name, type] of fileSystem[path]) {
      const item = document.createElement("div");
      item.className = "fs-item " + type;
      item.textContent = name;
      item.dataset.name = name;
      item.dataset.type = type;
      item.title = type === "folder" ? "Double-click to open " + name : name;

      item.addEventListener("click", () => {
        filesList.querySelectorAll(".fs-item").forEach(el => el.classList.remove("selected"));
        item.classList.add("selected");
      });

      if (type === "folder") {
        item.addEventListener("dblclick", () => navigate(joinPath(currentPath, name)));
      }

      filesList.appendChild(item);
    }

    document.querySelectorAll(".place").forEach(place => {
      place.classList.toggle("active", place.dataset.path === path);
    });
  }

  upButton.addEventListener("click", () => {
    if (currentPath === "/") return;
    const parts = currentPath.split("/").filter(Boolean);
    parts.pop();
    navigate(parts.length ? "/" + parts.join("/") : "/");
  });

  document.querySelectorAll(".place").forEach(place => {
    place.addEventListener("click", () => navigate(place.dataset.path));
  });

  const storageKey = "ubuntu-desktop-notepad-tabs-v1";
  const activeStorageKey = "ubuntu-desktop-notepad-active-v1";
  const tabsElement = document.getElementById("tabs");
  const editor = document.getElementById("editor");
  let tabs = [];
  let activeId = null;
  let nextTabNumber = 1;

  function loadTabs() {
    try {
      const saved = JSON.parse(localStorage.getItem(storageKey));
      if (Array.isArray(saved) && saved.length) {
        tabs = saved
          .filter(tab => tab && typeof tab.id === "string")
          .map(tab => ({
            id: tab.id,
            title: typeof tab.title === "string" ? tab.title : "Untitled",
            content: typeof tab.content === "string" ? tab.content : ""
          }));
      }
    } catch (_) {
      tabs = [];
    }

    if (!tabs.length) {
      tabs = [{ id: "tab-1", title: "Untitled 1", content: "" }];
    }

    nextTabNumber = tabs.reduce((maximum, tab) => {
      const match = tab.id.match(/^tab-(\d+)$/);
      return Math.max(maximum, match ? Number(match[1]) + 1 : 1);
    }, 1);

    const savedActive = localStorage.getItem(activeStorageKey);
    activeId = tabs.some(tab => tab.id === savedActive) ? savedActive : tabs[0].id;
    persistTabs();
  }

  function persistTabs() {
    localStorage.setItem(storageKey, JSON.stringify(tabs));
    localStorage.setItem(activeStorageKey, activeId);
  }

  function activeTab() {
    return tabs.find(tab => tab.id === activeId);
  }

  function renderTabs() {
    tabsElement.replaceChildren();

    tabs.forEach(tabData => {
      const tab = document.createElement("div");
      tab.className = "tab" + (tabData.id === activeId ? " active" : "");
      tab.textContent = tabData.title;
      tab.dataset.id = tabData.id;
      tab.setAttribute("role", "tab");
      tab.setAttribute("aria-selected", String(tabData.id === activeId));
      tab.addEventListener("click", () => switchTab(tabData.id));
      tabsElement.appendChild(tab);
    });

    const selected = activeTab();
    editor.value = selected ? selected.content : "";
  }

  function switchTab(id) {
    if (!tabs.some(tab => tab.id === id)) return;
    activeId = id;
    persistTabs();
    renderTabs();
    editor.focus();
  }

  function createTab() {
    const number = nextTabNumber++;
    const tab = {
      id: "tab-" + number,
      title: "Untitled " + number,
      content: ""
    };
    tabs.push(tab);
    activeId = tab.id;
    persistTabs();
    renderTabs();
    editor.focus();
    tabsElement.scrollLeft = tabsElement.scrollWidth;
  }

  document.getElementById("new-tab").addEventListener("click", createTab);

  editor.addEventListener("input", () => {
    const selected = activeTab();
    if (!selected) return;
    selected.content = editor.value;
    persistTabs();
  });

  function showWindow(windowElement) {
    windowElement.style.display = "flex";
    windowElement.style.zIndex = String(++topZ);
  }

  document.getElementById("open-files").addEventListener("click", () => {
    showWindow(document.getElementById("files-window"));
  });

  document.getElementById("open-notepad").addEventListener("click", () => {
    showWindow(document.getElementById("notepad-window"));
    editor.focus();
  });

  document.querySelectorAll(".win-close").forEach(button => {
    button.addEventListener("click", event => {
      event.stopPropagation();
      button.closest(".window").style.display = "none";
    });
  });

  document.querySelectorAll(".window").forEach(windowElement => {
    windowElement.addEventListener("mousedown", () => {
      windowElement.style.zIndex = String(++topZ);
    });

    const titlebar = windowElement.querySelector(".titlebar");
    let drag = null;

    titlebar.addEventListener("mousedown", event => {
      if (event.target.closest(".win-close")) return;
      const rect = windowElement.getBoundingClientRect();
      drag = {
        offsetX: event.clientX - rect.left,
        offsetY: event.clientY - rect.top
      };
      windowElement.style.zIndex = String(++topZ);
      event.preventDefault();
    });

    document.addEventListener("mousemove", event => {
      if (!drag) return;
      const maxLeft = Math.max(0, window.innerWidth - 120);
      const maxTop = Math.max(34, window.innerHeight - 70);
      const left = Math.min(maxLeft, Math.max(0, event.clientX - drag.offsetX));
      const top = Math.min(maxTop, Math.max(34, event.clientY - drag.offsetY));
      windowElement.style.left = left + "px";
      windowElement.style.top = top + "px";
    });

    document.addEventListener("mouseup", () => {
      drag = null;
    });
  });

  function updateClock() {
    const now = new Date();
    document.getElementById("clock").textContent =
      now.toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" }) +
      "  " +
      now.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
  }

  navigate("/");
  loadTabs();
  renderTabs();
  updateClock();
  setInterval(updateClock, 1000);
})();
</script>
</body>
</html>
